<section class="card automatic-responses-card"><div class="card-title"><div><h2>Respuestas automáticas</h2><p class="filter-help">Mensajes breves para eventos y cotizaciones. No usan la IA.</p></div></div><form wire:submit="save" class="automatic-response-form"><label>Tipo<select wire:model="type" class="input"><option value="event">Evento de paquete</option><option value="quote">Cotización</option></select></label><label>Clave<select wire:model="key" class="input"><option value="">Selecciona una clave</option>@if($type==='event')<option value="recibido_origen">Recibido en origen</option><option value="en_camino">En camino</option><option value="recibido_destino">Recibido en destino</option><option value="entregado">Entregado</option><option value="cancelado">Cancelado</option>@else<option value="EMS NAT">EMS nacional</option><option value="EMS INT">EMS internacional</option><option value="Delivery Express">Delivery Express</option>@endif</select></label><label>Nombre<input wire:model="name" class="input" placeholder="Ej. Paquete recibido"></label><label class="wide">Respuesta<input wire:model="template" class="input" placeholder="Usa {recipient}, {tracking_number}, {current_event} o {price}"></label><label class="check"><input wire:model="active" type="checkbox"> Activa</label><button class="primary-btn" type="submit">Guardar respuesta</button></form>@if(session('automaticResponseSaved'))<p class="saved-message">{{ session('automaticResponseSaved') }}</p>@endif<div class="automatic-response-list"><table><thead><tr><th>Tipo</th><th>Nombre</th><th>Clave</th><th>Respuesta</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>@forelse($responses as $response)<tr><td>{{ $response->type==='event'?'Evento':'Cotización' }}</td><td>{{ $response->name }}</td><td>{{ $response->key }}</td><td>{{ $response->template }}</td><td>{{ $response->active?'Activa':'Inactiva' }}</td><td><button type="button" wire:click="toggle({{ $response->id }})" class="secondary-btn">{{ $response->active?'Desactivar':'Activar' }}</button> <button type="button" wire:click="delete({{ $response->id }})" class="secondary-btn">Eliminar</button></td></tr>@empty<tr><td colspan="6" class="empty-log">Todavía no hay respuestas configuradas.</td></tr>@endforelse</tbody></table></div></section>
